    let target = "slskdn";
    let advanced = serde_json::json!({
        "virtualSoulfind": {
            "bridge": {
                "enabled": true,
                "port": 4323,
                "bindAddress": "127.0.0.1",
                "maxClients": 17,
                "requireAuth": false
            }
        }
    });
